package main

import "fmt"

type TLSConfig struct {
    Enabled bool
    Port    int
}

// Fehler: Value-Receiver verwirft Änderungen am Ende der Funktion!
func (cfg TLSConfig) EnableTLS() {
    cfg.Enabled = true
    cfg.Port = 443
}

func main() {
    cfg := TLSConfig{Enabled: false, Port: 80}
    cfg.EnableTLS()
    fmt.Printf("TLS=%v, Port=%d\n", cfg.Enabled, cfg.Port)
}

sections.solutionCode:
package main

import "fmt"

type TLSConfig struct {
    Enabled bool
    Port    int
}

// Korrekt: Pointer-Receiver modifiziert die Original-Speicheradresse
func (cfg *TLSConfig) EnableTLS() {
    cfg.Enabled = true
    cfg.Port = 443
}

func main() {
    cfg := TLSConfig{Enabled: false, Port: 80}
    cfg.EnableTLS()
    fmt.Printf("TLS=%v, Port=%d\n", cfg.Enabled, cfg.Port)
}
